memo = {}

def solve(blocks, is_alice):
    state = (tuple(sorted(blocks)), is_alice)
    if state in memo:
        return memo[state]

    # Check if any moves are possible
    possible_moves = []
    for i, l in enumerate(blocks):
        if l >= 2:
            for j in range(1, l):
                # Tile covers j and j+1
                new_blocks = list(blocks)
                new_blocks.pop(i)
                if j - 1 > 0:
                    new_blocks.append(j - 1)
                if l - j - 1 > 0:
                    new_blocks.append(l - j - 1)
                possible_moves.append(tuple(new_blocks))

    if not possible_moves:
        res = sum(blocks)
        memo[state] = res
        return res

    if is_alice:
        res = -float('inf')
        for next_blocks in possible_moves:
            res = max(res, solve(next_blocks, False))
    else:
        res = float('inf')
        for next_blocks in possible_moves:
            res = min(res, solve(next_blocks, True))

    memo[state] = res
    return res

for n in range(1, 21):
    memo = {}
    print(f"n={n}, f(n)={solve((n,), True)}")

